#include <bits/stdc++.h>
using namespace std;
struct Parser{string s;size_t p=0;bool ok=true;void ws(){while(p<s.size()&&isspace((unsigned char)s[p]))++p;}bool eat(char c){ws();if(p<s.size()&&s[p]==c){++p;return true;}return false;}bool factor(){ws();if(eat('(')){if(!expr()||!eat(')'))return false;return true;}ws();if(p<s.size()&&(isalpha((unsigned char)s[p])||isdigit((unsigned char)s[p])||s[p]=='_')){while(p<s.size()&&(isalnum((unsigned char)s[p])||s[p]=='_'||s[p]=='.'))++p;return true;}return false;}bool term(){if(!factor())return false;while(true){ws();if(p<s.size()&&(s[p]=='*'||s[p]=='/')){++p;if(!factor())return false;}else break;}return true;}bool expr(){if(!term())return false;while(true){ws();if(p<s.size()&&(s[p]=='+'||s[p]=='-')){++p;if(!term())return false;}else break;}return true;}bool parse(){bool r=expr();ws();return r&&p==s.size();}};
int main(){string s;getline(cin,s);Parser p{s};cout<<(p.parse()?"Accepted: valid arithmetic expression":"Rejected: syntax error")<<'\n';}
